// Turns the form submission + Config into one item per seed keyword.
// Every item carries the full settings so downstream nodes can read them.
const input = $input.first().json;

const seeds = [
	...new Set(
		String(input['Seed keywords'] || '')
			.split(/[\n,;]+/)
			.map((s) => s.trim().toLowerCase())
			.filter(Boolean),
	),
].slice(0, 20);

if (!seeds.length) {
	throw new Error('Enter at least one seed keyword (one per line or comma separated).');
}

const domain = String(input['Website domain'] || input.SITE_DOMAIN || '')
	.trim()
	.toLowerCase()
	.replace(/^https?:\/\//, '')
	.replace(/^www\./, '')
	.replace(/\/.*$/, '');

const toNumber = (value, fallback) => {
	const n = Number(value);
	return Number.isFinite(n) && String(value).trim() !== '' ? n : fallback;
};

const settings = {
	seeds,
	domain,
	location_name: input['Country'] || input.DEFAULT_COUNTRY || 'Netherlands',
	language_name: input['Language'] || input.DEFAULT_LANGUAGE || 'Dutch',
	max_kd: toNumber(input['Max keyword difficulty (0-100)'], 30),
	min_volume: toNumber(input['Min monthly searches'], 20),
	serp_checks: Math.min(toNumber(input['Keywords to check in Google'], 10), 30),
	business: input['What do you sell and to whom?'] || input.BUSINESS_DESCRIPTION || '',
	competitors: String(input['Known competitors (optional)'] || '')
		.split(/[\n,;]+/)
		.map((s) => s.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''))
		.filter(Boolean),
	claude_model: input.CLAUDE_MODEL,
	sheet_id: input.SHEET_ID,
	researched_at: new Date().toISOString(),
};

return seeds.map((seed) => ({ json: { seed, ...settings } }));

// Merges every DataForSEO keyword source, dedupes, scores and picks the
// low-hanging fruit: keywords with real demand and low difficulty, plus
// keywords the site already ranks 4-20 for ("striking distance").
const cfg = $('Prepare seeds').first().json;

const QUESTION_START =
	// English, Dutch, French and German question openers.
	/^(what|how|why|when|where|which|who|whom|whose|can|could|does|do|did|is|are|was|should|will|would|wat|hoe|waarom|wanneer|waar|welke|wie|kan|kun|kunnen|mag|moet|moeten|zijn|wordt|heb|hebben|hoeveel|comment|pourquoi|quand|quel|quelle|warum|wann|welche|wo)\b/i;

const INTENT_WEIGHT = {
	informational: 1,
	commercial: 1.3,
	transactional: 1.15,
	navigational: 0.3,
};

function resultItems(nodeName) {
	try {
		return $(nodeName)
			.all()
			.flatMap((item) => item.json.tasks || [])
			.flatMap((task) => task.result || [])
			.flatMap((result) => result.items || []);
	} catch (error) {
		// Node did not run or errored (e.g. no domain for ranked keywords).
		return [];
	}
}

const rows = new Map();

function upsert(data, source, extra = {}) {
	if (!data || !data.keyword) return;
	const keyword = String(data.keyword).trim().toLowerCase();
	const info = data.keyword_info || {};
	const row = rows.get(keyword) || {
		keyword,
		search_volume: null,
		keyword_difficulty: null,
		cpc: null,
		competition: null,
		intent: 'unknown',
		current_position: null,
		current_url: '',
		sources: new Set(),
	};
	row.search_volume ??= info.search_volume ?? null;
	row.cpc ??= info.cpc ?? null;
	row.competition ??= info.competition ?? null;
	row.keyword_difficulty ??= data.keyword_properties?.keyword_difficulty ?? null;
	if (row.intent === 'unknown' && data.search_intent_info?.main_intent) {
		row.intent = data.search_intent_info.main_intent;
	}
	row.sources.add(source);
	Object.assign(row, extra);
	rows.set(keyword, row);
}

resultItems('DataForSEO: Keyword suggestions').forEach((i) => upsert(i, 'suggestions'));
resultItems('DataForSEO: Related keywords').forEach((i) => upsert(i.keyword_data, 'related'));
resultItems('DataForSEO: Keyword ideas').forEach((i) => upsert(i, 'ideas'));
resultItems('DataForSEO: Your striking-distance keywords').forEach((i) => {
	const serpItem = i.ranked_serp_element?.serp_item || {};
	upsert(i.keyword_data, 'your-rankings', {
		current_position: serpItem.rank_group ?? null,
		current_url: serpItem.url || '',
	});
});

// Relevance: keep keywords that share a meaningful word with a seed,
// or that the site already ranks for.
const seedTokens = new Set(
	cfg.seeds.flatMap((s) => s.split(/\s+/)).filter((t) => t.length >= 3),
);
const isRelevant = (row) =>
	row.current_position !== null ||
	row.keyword.split(/\s+/).some((t) => seedTokens.has(t));

const brandBlocklist = cfg.competitors.map((c) => c.split('.')[0]).filter((c) => c.length >= 3);
const isCompetitorBranded = (row) => brandBlocklist.some((b) => row.keyword.includes(b));

const scored = [...rows.values()]
	.filter((row) => isRelevant(row) && !isCompetitorBranded(row))
	.map((row) => {
		const volume = row.search_volume ?? 0;
		const kdKnown = row.keyword_difficulty !== null;
		const kd = kdKnown ? row.keyword_difficulty : 50;
		const cpc = row.cpc ?? 0;
		const striking = row.current_position !== null && row.current_position >= 4 && row.current_position <= 20;
		const isQuestion = QUESTION_START.test(row.keyword) || row.keyword.includes('?');
		// Already ranking 4-20 means Google trusts the page for this topic, so
		// difficulty matters less and the upside is bigger.
		const difficultyFactor = Math.pow((100 - kd) / 100, 2);
		const opportunity =
			Math.sqrt(volume) *
			(striking ? Math.max(difficultyFactor, 0.5) : difficultyFactor) *
			(INTENT_WEIGHT[row.intent] ?? 1) *
			(1 + Math.min(cpc, 10) / 10) *
			(striking ? 2 : 1) *
			(isQuestion ? 1.1 : 1);
		const lowHangingFruit =
			striking || (kdKnown && kd <= cfg.max_kd && volume >= cfg.min_volume);
		return {
			...row,
			sources: [...row.sources].join(', '),
			is_question: isQuestion,
			striking_distance: striking,
			low_hanging_fruit: lowHangingFruit,
			opportunity_score: Math.round(opportunity * 10) / 10,
		};
	})
	.sort((a, b) => b.opportunity_score - a.opportunity_score);

const questions = scored.filter((r) => r.is_question);
const candidates = scored.filter((r) => r.low_hanging_fruit);

if (!candidates.length) {
	throw new Error(
		`No low-hanging fruit found among ${scored.length} relevant keywords. ` +
			'Try broader seeds, a higher max keyword difficulty or a lower minimum volume.',
	);
}

// Questions from the dataset that belong to a candidate keyword.
const relatedQuestions = (keyword) => {
	const tokens = keyword.split(/\s+/).filter((t) => t.length >= 3 && !QUESTION_START.test(t));
	return questions
		.filter((q) => q.keyword !== keyword && tokens.length && tokens.every((t) => q.keyword.includes(t)))
		.slice(0, 8)
		.map((q) => q.keyword);
};

const summary = {
	total_keywords: rows.size,
	relevant_keywords: scored.length,
	low_hanging_fruit: candidates.length,
	question_keywords: questions.length,
};

return candidates.slice(0, cfg.serp_checks).map((row) => ({
	json: { ...row, related_questions: relatedQuestions(row.keyword), summary },
}));

// Reads the live Google results for each candidate and adds what we need to
// position ourselves: who ranks, what people also ask, and how beatable the
// SERP looks (forums/UGC in the top 10 = weak SERP).
const cfg = $('Prepare seeds').first().json;
const candidates = $('Score low-hanging fruit').all();

const UGC_DOMAINS = [
	'reddit.com',
	'quora.com',
	'medium.com',
	'linkedin.com',
	'facebook.com',
	'pinterest.com',
	'tiktok.com',
	'stackexchange.com',
	'stackoverflow.com',
	'tweakers.net',
	'zhihu.com',
];
const isUgc = (domain) =>
	UGC_DOMAINS.some((d) => domain === d || domain.endsWith(`.${d}`)) || /forum|community|discuss/.test(domain);

return $input.all().map((item, index) => {
	const candidate = candidates[index].json;
	const result = item.json.tasks?.[0]?.result?.[0] || {};
	const serpItems = result.items || [];

	const organic = serpItems
		.filter((i) => i.type === 'organic')
		.slice(0, 10)
		.map((i) => ({
			rank: i.rank_group,
			domain: (i.domain || '').replace(/^www\./, ''),
			url: i.url,
			title: i.title,
		}));

	const peopleAlsoAsk = serpItems
		.filter((i) => i.type === 'people_also_ask')
		.flatMap((i) => i.items || [])
		.map((q) => q.title)
		.filter(Boolean);

	const relatedSearches = serpItems
		.filter((i) => i.type === 'related_searches')
		.flatMap((i) => i.items || [])
		.filter((s) => typeof s === 'string');

	const features = [...new Set(serpItems.map((i) => i.type).filter((t) => t !== 'organic'))];
	const ugcCount = organic.filter((o) => isUgc(o.domain)).length;
	const ours = cfg.domain ? organic.find((o) => o.domain === cfg.domain || o.domain.endsWith(`.${cfg.domain}`)) : null;

	const kd = candidate.keyword_difficulty ?? 50;
	let serpStrength = 'medium';
	if (ugcCount >= 2 || kd <= 15) serpStrength = 'weak';
	if (ugcCount === 0 && kd >= 45) serpStrength = 'strong';

	return {
		json: {
			...candidate,
			current_position: ours ? ours.rank : candidate.current_position,
			current_url: ours ? ours.url : candidate.current_url,
			serp_strength: serpStrength,
			weak_serp_signals: ugcCount ? `${ugcCount} forum/UGC results in top 10` : '',
			serp_features: features,
			top_competitors: organic.filter((o) => o.domain !== cfg.domain).slice(0, 5),
			people_also_ask: [...new Set(peopleAlsoAsk)].slice(0, 8),
			related_searches: relatedSearches.slice(0, 8),
		},
	};
});

// Builds one Claude request that clusters the candidates and decides how we
// position each article so it is different from what already ranks.
const cfg = $('Prepare seeds').first().json;
const keywords = $input.all().map((i) => i.json);

const compact = keywords.map((k) => ({
	keyword: k.keyword,
	volume: k.search_volume,
	kd: k.keyword_difficulty,
	intent: k.intent,
	opportunity: k.opportunity_score,
	we_rank: k.current_position,
	serp_strength: k.serp_strength,
	competitors: k.top_competitors.map((c) => `${c.rank}. ${c.domain} — ${c.title}`),
	people_also_ask: k.people_also_ask,
	related_questions: k.related_questions,
}));

const system = `You are a senior SEO content strategist. You turn keyword data into a content plan a small team can execute.
Rules:
- Use only the data provided. Never invent search volumes or rankings.
- Group keywords that would be answered by the same article into one cluster (same search intent = same page).
- For every keyword, decide how we position ourselves so the article is clearly different from and better than the current top results (a unique angle, format, data, or experience the competitors lack).
- Write titles, angles and questions in ${cfg.language_name}.
- Answer with JSON only, no prose and no code fences.`;

const user = `Business: ${cfg.business || 'not provided'}
Website: ${cfg.domain || 'not provided'}
Market: ${cfg.location_name} / ${cfg.language_name}

Candidate low-hanging-fruit keywords with live SERP data:
${JSON.stringify(compact, null, 1)}

Return this JSON shape:
{
  "clusters": [
    { "name": "string", "pillar_keyword": "string", "keywords": ["string"], "why_we_can_win": "string" }
  ],
  "keywords": [
    {
      "keyword": "exact keyword from the input",
      "cluster": "cluster name",
      "priority": 1,
      "content_type": "how-to guide | listicle | comparison | explainer | checklist | case study | glossary",
      "suggested_title": "string, max 60 characters",
      "angle": "one sentence: the unique angle we take",
      "differentiator": "one sentence: what we add that the top 5 results do not",
      "questions_to_answer": ["the 4-8 most important questions the article must answer, using people_also_ask and related_questions"]
    }
  ]
}
priority: 1 = write first (high opportunity, weak SERP, strong business fit), 3 = later.
Include every input keyword exactly once in "keywords".`;

return [
	{
		json: {
			anthropic_body: {
				model: cfg.claude_model,
				max_tokens: 8000,
				system,
				messages: [{ role: 'user', content: user }],
			},
		},
	},
];

// Combines Claude's plan with the SERP data into flat rows for the
// "Keywords" sheet (the backlog the blog writer workflow picks from).
const cfg = $('Prepare seeds').first().json;
const keywords = $('Add SERP insights').all().map((i) => i.json);

const text = ($input.first().json.content || [])
	.filter((block) => block.type === 'text')
	.map((block) => block.text)
	.join('');
const jsonText = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);

let plan = { clusters: [], keywords: [] };
try {
	plan = JSON.parse(jsonText);
} catch (error) {
	throw new Error(`Claude did not return valid JSON. Raw answer starts with: ${text.slice(0, 300)}`);
}

const planByKeyword = new Map(
	(plan.keywords || []).map((k) => [String(k.keyword).trim().toLowerCase(), k]),
);
const clusterWhy = new Map((plan.clusters || []).map((c) => [c.name, c.why_we_can_win]));
const list = (values) => (values || []).filter(Boolean).join(' | ');

return keywords.map((k) => {
	const p = planByKeyword.get(k.keyword) || {};
	return {
		json: {
			keyword: k.keyword,
			cluster: p.cluster || '',
			priority: p.priority ?? 3,
			opportunity_score: k.opportunity_score,
			search_volume: k.search_volume ?? 'unknown',
			keyword_difficulty: k.keyword_difficulty ?? 'unknown',
			cpc: k.cpc ?? '',
			intent: k.intent,
			current_position: k.current_position ?? '',
			current_url: k.current_url || '',
			serp_strength: k.serp_strength,
			weak_serp_signals: k.weak_serp_signals,
			top_competitors: list(k.top_competitors.map((c) => c.url)),
			people_also_ask: list(k.people_also_ask),
			questions_to_answer: list(p.questions_to_answer || k.related_questions),
			angle: p.angle || '',
			differentiator: p.differentiator || '',
			why_we_can_win: clusterWhy.get(p.cluster) || '',
			suggested_title: p.suggested_title || '',
			content_type: p.content_type || '',
			status: 'ready',
			location: cfg.location_name,
			language: cfg.language_name,
			researched_at: cfg.researched_at,
			post_slug: '',
		},
	};
});
